"""GFF3-driven variant annotation for parsed VCF documents.

Public API:

- :class:`AnnotationFormatError` — malformed GFF3 input (bad CDS rows,
  coordinates or phase, missing Parent, a strand other than ``+``/``-``,
  CDS fragments spanning several sequences or contradictory reading
  frames) or a VCF that already declares or uses the ``GVANN`` key.
- :func:`annotate_vcf` — append one ``GVANN`` INFO item per ALT allele to
  every record of a :class:`~genome_variant.vcf.VcfFile`.

CDS features are grouped by their GFF3 ``Parent`` attribute into
transcripts.  The standard genetic code is used; only ``A``/``C``/``G``/``T``
single-base substitutions inside a CDS are annotated with a coding
consequence.  Every other ALT (indels, ambiguous or symbolic alleles)
receives ``UNSUPPORTED``/``MODIFIER`` and records without a CDS hit
receive ``NON_CODING``/``MODIFIER``.
"""

from __future__ import annotations

import io
import os
from collections import defaultdict
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord
from .vcf import (
    ReferenceMismatchError,
    VcfFile,
    VcfFormatError,
    VcfHeader,
    VcfRecord,
)

__all__ = [
    "AnnotationFormatError",
    "annotate_vcf",
]

GVANN_ID = "GVANN"

#: GFF3 column 3 type that delimits the annotation ranges.
_CDS_TYPE = "CDS"

#: Standard genetic code, codons read on the coding strand.
_GENETIC_CODE = {
    "TTT": "F", "TTC": "F", "TTA": "L", "TTG": "L",
    "CTT": "L", "CTC": "L", "CTA": "L", "CTG": "L",
    "ATT": "I", "ATC": "I", "ATA": "I", "ATG": "M",
    "GTT": "V", "GTC": "V", "GTA": "V", "GTG": "V",
    "TCT": "S", "TCC": "S", "TCA": "S", "TCG": "S",
    "CCT": "P", "CCC": "P", "CCA": "P", "CCG": "P",
    "ACT": "T", "ACC": "T", "ACA": "T", "ACG": "T",
    "GCT": "A", "GCC": "A", "GCA": "A", "GCG": "A",
    "TAT": "Y", "TAC": "Y", "TAA": "*", "TAG": "*",
    "CAT": "H", "CAC": "H", "CAA": "Q", "CAG": "Q",
    "AAT": "N", "AAC": "N", "AAA": "K", "AAG": "K",
    "GAT": "D", "GAC": "D", "GAA": "E", "GAG": "E",
    "TGT": "C", "TGC": "C", "TGA": "*", "TGG": "W",
    "CGT": "R", "CGC": "R", "CGA": "R", "CGG": "R",
    "AGT": "S", "AGC": "S", "AGA": "R", "AGG": "R",
    "GGT": "G", "GGC": "G", "GGA": "G", "GGG": "G",
}

_COMPLEMENT = str.maketrans("ACGT", "TGCA")

#: Impact each consequence maps to.
_CONSEQUENCE_IMPACT = {
    "START_LOST": "HIGH",
    "STOP_GAINED": "HIGH",
    "STOP_LOST": "HIGH",
    "SYNONYMOUS": "LOW",
    "MISSENSE": "MODERATE",
}

_GVANN_HEADER = (
    '##INFO=<ID=GVANN,Number=.,Type=String,Description="Genome variant '
    'annotation: ALT|CONSEQUENCE|IMPACT|TRANSCRIPT|CDS_POS|CODON_CHANGE|'
    'AA_CHANGE; multiple transcripts are comma separated">'
)

_NO_TRANSCRIPT = ".|.|.|."


class AnnotationFormatError(ValueError):
    """Malformed GFF3 data or a VCF that already carries ``GVANN``."""


@dataclass(frozen=True)
class _CdsFragment:
    """One CDS GFF3 row: 1-based inclusive interval on one sequence."""

    seqid: str
    start: int
    end: int
    strand: str
    phase: int
    line_number: int


@dataclass(frozen=True)
class _CodonSite:
    """Everything known about one coding base without reading the reference."""

    cds_pos: int
    codon_number: int
    position_in_codon: int
    codon_indices: tuple[int, ...]


@dataclass(frozen=True)
class _Transcript:
    """A Parent group assembled into coding-strand codons."""

    parent: str
    strand: str
    seqid: str
    #: Genomic 0-based index -> coding site, for bases in complete codons.
    sites: dict[int, _CodonSite]
    #: Original fragments as (1-based start, 1-based end, source line).
    fragments: tuple[tuple[int, int, int], ...]


def _gff_error(source: str, line_number: int, message: str) -> AnnotationFormatError:
    return AnnotationFormatError(f"{source}:{line_number}: {message}")


def _decode_gff3(text: str) -> str:
    """Decode one percent-encoded GFF3 attribute value component."""
    output: list[str] = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "%":
            if index + 2 >= len(text):
                raise ValueError("truncated percent escape")
            try:
                output.append(chr(int(text[index + 1 : index + 3], 16)))
            except ValueError:
                raise ValueError(
                    f"invalid percent escape {text[index:index + 3]!r}"
                )
            index += 3
        else:
            output.append(char)
            index += 1
    return "".join(output)


def _parse_attributes(
    column: str, source: str, line_number: int
) -> dict[str, list[str]]:
    """Parse GFF3 column 9 into tag -> decoded values in column order."""
    attributes: dict[str, list[str]] = {}
    if column == "":
        return attributes
    for assignment in column.split(";"):
        if not assignment:
            raise _gff_error(source, line_number, "empty GFF3 attribute assignment")
        if "=" not in assignment:
            raise _gff_error(
                source, line_number, f"GFF3 attribute {assignment!r} lacks '='"
            )
        tag, raw_values = assignment.split("=", 1)
        if not tag:
            raise _gff_error(source, line_number, "empty GFF3 attribute tag")
        values: list[str] = []
        for raw_value in raw_values.split(","):
            try:
                values.append(_decode_gff3(raw_value))
            except ValueError as exc:
                raise _gff_error(
                    source, line_number, f"GFF3 attribute {tag!r}: {exc}"
                ) from None
        attributes.setdefault(tag, []).extend(values)
    return attributes


def _parse_cds_fragments(
    stream: Iterable[str], source: str
) -> dict[str, list[_CdsFragment]]:
    """Read a GFF3 stream and collect CDS fragments keyed by Parent."""
    fragments: dict[str, list[_CdsFragment]] = defaultdict(list)
    in_fasta = False
    for line_number, raw_line in enumerate(stream, start=1):
        line = raw_line.rstrip("\r\n")
        if line == "##FASTA":
            # An optional embedded FASTA section follows; it is not used.
            in_fasta = True
            continue
        if in_fasta or not line or line.startswith("#"):
            continue
        columns = line.split("\t")
        if len(columns) != 9:
            raise _gff_error(
                source,
                line_number,
                f"expected 9 tab-separated GFF3 columns, got {len(columns)}",
            )
        if columns[2] != _CDS_TYPE:
            continue

        seqid = columns[0]
        start_text, end_text = columns[3], columns[4]
        strand, phase_text = columns[6], columns[7]
        attributes_text = columns[8]

        if not seqid:
            raise _gff_error(source, line_number, "CDS feature has an empty seqid")
        try:
            start = int(start_text)
        except ValueError:
            raise _gff_error(
                source, line_number, f"CDS start {start_text!r} is not an integer"
            ) from None
        try:
            end = int(end_text)
        except ValueError:
            raise _gff_error(
                source, line_number, f"CDS end {end_text!r} is not an integer"
            ) from None
        if start < 1 or end < 1:
            raise _gff_error(
                source,
                line_number,
                f"CDS coordinates {start}-{end} are not 1-based positive",
            )
        if start > end:
            raise _gff_error(
                source,
                line_number,
                f"CDS start {start} is greater than its end {end}",
            )
        if strand not in ("+", "-"):
            raise _gff_error(
                source, line_number, f"CDS strand {strand!r} is not '+' or '-'"
            )
        if phase_text not in ("0", "1", "2"):
            raise _gff_error(
                source,
                line_number,
                f"CDS phase {phase_text!r} is not one of '0', '1', '2'",
            )

        attributes = _parse_attributes(attributes_text, source, line_number)
        parents = attributes.get("Parent")
        if not parents:
            raise _gff_error(
                source, line_number, "CDS feature is missing a Parent attribute"
            )
        if any(parent == "" for parent in parents):
            raise _gff_error(
                source, line_number, "CDS feature has an empty Parent value"
            )
        phase = int(phase_text)
        for parent in parents:
            fragments[parent].append(
                _CdsFragment(
                    seqid=seqid,
                    start=start,
                    end=end,
                    strand=strand,
                    phase=phase,
                    line_number=line_number,
                )
            )
    return fragments


def _build_layout(
    parent: str, fragments: list[_CdsFragment], source: str
) -> list[int]:
    """Return CDS bases as genomic 0-based indices in coding order.

    Validates that every fragment shares one sequence and one strand and
    that each fragment's declared phase agrees with the assembled frame.
    """
    first = fragments[0]
    for fragment in fragments[1:]:
        if fragment.seqid != first.seqid:
            raise _gff_error(
                source,
                fragment.line_number,
                f"CDS for Parent {parent!r} spans multiple sequences "
                f"({first.seqid!r} and {fragment.seqid!r})",
            )
        if fragment.strand != first.strand:
            raise _gff_error(
                source,
                fragment.line_number,
                f"CDS for Parent {parent!r} mixes strands "
                f"({first.strand!r} and {fragment.strand!r})",
            )

    # Coding order: ascending coordinates on the plus strand, descending
    # on the minus strand (each minus-strand fragment read in reverse).
    ordered = sorted(fragments, key=lambda fragment: fragment.start)
    reverse = first.strand == "-"
    if reverse:
        ordered.reverse()

    layout: list[int] = []
    consumed = 0
    for fragment in ordered:
        # Phase is the number of coding bases missing at this fragment's
        # 5' edge before the next codon boundary: 1 -> 2, 2 -> 1.
        expected_phase = (3 - (consumed % 3)) % 3
        if fragment.phase != expected_phase:
            raise _gff_error(
                source,
                fragment.line_number,
                f"CDS phase {fragment.phase} for Parent {parent!r} contradicts "
                f"the assembled reading frame (expected {expected_phase})",
            )
        length = fragment.end - fragment.start + 1
        indices = range(fragment.start - 1, fragment.end)
        if reverse:
            indices = reversed(indices)
        layout.extend(indices)
        consumed += length

    return layout


def _build_transcript(
    parent: str, fragments: list[_CdsFragment], source: str
) -> _Transcript:
    layout = _build_layout(parent, fragments, source)
    sites: dict[int, _CodonSite] = {}
    for codon_number, start in enumerate(range(0, len(layout) - 2, 3), start=1):
        codon_indices = tuple(layout[start : start + 3])
        for position_in_codon, genomic_index in enumerate(codon_indices):
            sites[genomic_index] = _CodonSite(
                cds_pos=start + position_in_codon + 1,
                codon_number=codon_number,
                position_in_codon=position_in_codon,
                codon_indices=codon_indices,
            )
    return _Transcript(
        parent=parent,
        strand=fragments[0].strand,
        seqid=fragments[0].seqid,
        sites=sites,
        fragments=tuple(
            sorted(
                (fragment.start, fragment.end, fragment.line_number)
                for fragment in fragments
            )
        ),
    )


def _read_gff3(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> tuple[tuple[_Transcript, ...], str]:
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        fragments = _parse_cds_fragments(stream, source_name)
        transcripts = [
            _build_transcript(parent, parent_fragments, source_name)
            for parent, parent_fragments in fragments.items()
        ]
        transcripts.sort(key=lambda transcript: transcript.parent)
        return tuple(transcripts), source_name
    finally:
        if close:
            stream.close()


def _build_reference(
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> tuple[dict[str, str], set[str]]:
    """Map CHROM to upper-case sequence, tracking duplicated identifiers."""
    if isinstance(reference, Mapping):
        return {key: value.upper() for key, value in reference.items()}, set()
    sequences: dict[str, str] = {}
    duplicates: set[str] = set()
    for record in reference:
        if record.identifier in sequences:
            duplicates.add(record.identifier)
        else:
            sequences[record.identifier] = record.sequence.upper()
    return sequences, duplicates


def _is_acgt_snv(ref: str, alt: str) -> bool:
    return (
        len(ref) == 1
        and len(alt) == 1
        and ref in "ACGT"
        and alt in "ACGT"
        and ref != alt
    )


def _classify(codon_number: int, old_codon: str, new_codon: str) -> tuple[str, str]:
    old_aa = _GENETIC_CODE[old_codon]
    new_aa = _GENETIC_CODE[new_codon]
    if codon_number == 1 and old_aa == "M" and new_aa != "M":
        consequence = "START_LOST"
    elif old_aa != "*" and new_aa == "*":
        consequence = "STOP_GAINED"
    elif old_aa == "*" and new_aa != "*":
        consequence = "STOP_LOST"
    elif old_aa == new_aa:
        consequence = "SYNONYMOUS"
    else:
        consequence = "MISSENSE"
    return consequence, _CONSEQUENCE_IMPACT[consequence]


def _annotate_alt(
    record: VcfRecord,
    alt: str,
    transcripts: tuple[_Transcript, ...],
    chromosome: str,
) -> str:
    if not _is_acgt_snv(record.ref, alt):
        return f"{alt}|UNSUPPORTED|MODIFIER|{_NO_TRANSCRIPT}"

    genomic_index = record.pos - 1
    items: list[str] = []
    # transcripts are already ordered by Parent, so hits stay lexicographic.
    for transcript in transcripts:
        if transcript.seqid != record.chrom:
            continue
        site = transcript.sites.get(genomic_index)
        if site is None:
            continue

        old_bases: list[str] = []
        for index in site.codon_indices:
            base = chromosome[index]
            if transcript.strand == "-":
                base = base.translate(_COMPLEMENT)
            old_bases.append(base)
        if any(base not in "ACGT" for base in old_bases):
            # Ambiguous coding context: the standard code cannot judge it.
            items.append(
                f"{alt}|UNSUPPORTED|MODIFIER|{transcript.parent}|"
                f"{site.cds_pos}|.|."
            )
            continue

        old_codon = "".join(old_bases)
        alt_coding_base = (
            alt.translate(_COMPLEMENT) if transcript.strand == "-" else alt
        )
        new_bases = list(old_codon)
        new_bases[site.position_in_codon] = alt_coding_base
        new_codon = "".join(new_bases)

        consequence, impact = _classify(site.codon_number, old_codon, new_codon)
        old_aa = _GENETIC_CODE[old_codon]
        new_aa = _GENETIC_CODE[new_codon]
        items.append(
            "|".join(
                (
                    alt,
                    consequence,
                    impact,
                    transcript.parent,
                    str(site.cds_pos),
                    f"{old_codon}>{new_codon}",
                    f"{old_aa}>{new_aa}",
                )
            )
        )

    if not items:
        return f"{alt}|NON_CODING|MODIFIER|{_NO_TRANSCRIPT}"
    return ",".join(items)


def _meta_declares_gvann(line: str) -> bool:
    if not line.startswith("##"):
        return False
    body = line[2:]
    if body == GVANN_ID or body.startswith(GVANN_ID + "="):
        return True
    # Structured meta-information, e.g. ##INFO=<ID=GVANN,...>.
    return f"<ID={GVANN_ID}," in body or f"<ID={GVANN_ID}>" in body


def _info_has_gvann(info: str) -> bool:
    if not info:
        return False
    for item in info.split(";"):
        if item.split("=", 1)[0] == GVANN_ID:
            return True
    return False


def _check_existing_gvann(document: VcfFile) -> None:
    for line in document.header.meta_lines:
        if _meta_declares_gvann(line):
            raise AnnotationFormatError(
                f"{GVANN_ID} is already declared in the VCF meta-information"
            )
    for record in document.records:
        if _info_has_gvann(record.info):
            source = document.source
            prefix = f"{source}:{record.line_number}: " if source and record.line_number else ""
            raise AnnotationFormatError(
                f"{prefix}{GVANN_ID} is already present in a VCF record"
            )


def annotate_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
    features: "str | os.PathLike[str] | io.TextIOBase",
) -> VcfFile:
    """Annotate every ALT allele of *document* with a ``GVANN`` INFO item.

    *reference* is a mapping of CHROM to upper-case sequence or an
    iterable of :class:`~genome_variant.sequence_io.SequenceRecord`;
    *features* is a GFF3 text path or text stream whose CDS features
    define the annotated ranges, grouped into transcripts by ``Parent``.

    Record order, ALT order, sample columns and every existing field are
    preserved; one unique ``##INFO`` declaration for ``GVANN`` is
    appended to the meta-information and a ``GVANN`` item is appended to
    the end of each record's INFO column (starting the column when INFO
    was missing).  Coding consequences are ``START_LOST``,
    ``STOP_GAINED``, ``STOP_LOST``, ``SYNONYMOUS`` and ``MISSENSE`` with
    impacts ``HIGH``, ``HIGH``, ``HIGH``, ``LOW`` and ``MODERATE``;
    transcripts are listed by lexicographic Parent.  SNVs outside every
    CDS get ``NON_CODING``/``MODIFIER`` and non-SNV, ambiguous or
    symbolic ALTs get ``UNSUPPORTED``/``MODIFIER``.

    Every record's REF is checked against the reference first.  Raises
    :class:`~genome_variant.vcf.ReferenceMismatchError` for an
    absent/duplicated CHROM or a REF mismatch,
    :class:`~genome_variant.vcf.VcfFormatError` for an out-of-bounds
    record and :class:`AnnotationFormatError` for malformed GFF3 data or
    a document that already declares or uses ``GVANN``.
    """
    transcripts, features_source = _read_gff3(features)
    _check_existing_gvann(document)
    sequences, duplicates = _build_reference(reference)

    # A CDS interval cannot run past the end of the sequence it names.
    for transcript in transcripts:
        chromosome = sequences.get(transcript.seqid)
        if chromosome is None:
            continue
        length = len(chromosome)
        for start, end, line_number in transcript.fragments:
            if end > length:
                raise AnnotationFormatError(
                    f"{features_source}:{line_number}: CDS coordinates "
                    f"{start}-{end} run past the end of sequence "
                    f"{transcript.seqid!r} (length {length})"
                )

    annotated_records: list[VcfRecord] = []
    for record in document.records:
        if record.chrom in duplicates:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than "
                "once in the reference"
            )
        try:
            chromosome = sequences[record.chrom]
        except KeyError:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: no matching record in "
                "the reference"
            ) from None

        end = record.pos - 1 + len(record.ref)
        if record.pos < 1 or end > len(chromosome):
            prefix = (
                f"{document.source}:{record.line_number}: "
                if document.source and record.line_number
                else ""
            )
            raise VcfFormatError(
                f"{prefix}CHROM {record.chrom} POS {record.pos}: REF of length "
                f"{len(record.ref)} is out of bounds for a reference of length "
                f"{len(chromosome)}"
            )
        expected = chromosome[record.pos - 1 : end]
        if expected != record.ref:
            raise ReferenceMismatchError(
                f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
                f"reference: expected {expected!r}, found {record.ref!r}"
            )

        items = [
            _annotate_alt(record, alt, transcripts, chromosome)
            for alt in record.alt
        ]
        gvann = f"{GVANN_ID}=" + ",".join(items)
        # The lone "." is the VCF missing-value placeholder, i.e. no INFO:
        # GVANN then starts the column; otherwise it is appended last.
        if record.info and record.info != ".":
            info = f"{record.info};{gvann}"
        else:
            info = gvann
        annotated_records.append(replace(record, info=info))

    header = VcfHeader(
        meta_lines=document.header.meta_lines + (_GVANN_HEADER,),
        samples=document.header.samples,
    )
    return VcfFile(header, tuple(annotated_records), document.source)

"""Reference-aware VCF reading, normalization and writing.

Public API:

- :class:`VcfHeader` — the ``##`` meta-information lines (kept verbatim
  and in order) together with the sample names declared by the single
  ``#CHROM`` column header.
- :class:`VcfRecord` — one VCF data row: the eight fixed columns, an
  optional ``FORMAT`` column and the per-sample text columns.
- :class:`VcfFile` — a parsed VCF document pairing a header with its
  records.
- :func:`read_vcf` — parse VCF text from a path or text stream.
- :func:`normalize_record` / :func:`normalize_vcf` — trim common
  allele suffixes/prefixes and left-align indels against a reference.
- :func:`render_vcf` / :func:`write_vcf` — serialize a VCF document
  with tabs and ``"\\n"``.

Ordinary sequence alleles only contain the IUPAC DNA symbols
``ACGTRYSWKMBDHVN`` (lower-case input is upper-cased).  Records carrying
symbolic (``<...>``), break-end (brackets or a ``.`` join), spanning
(``*``) or missing (``.``) ALT alleles are validated against the
reference but never trimmed or shifted.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord, _VALID_BASES

__all__ = [
    "VcfHeader",
    "VcfRecord",
    "VcfFile",
    "VcfFormatError",
    "ReferenceMismatchError",
    "read_vcf",
    "normalize_record",
    "normalize_vcf",
    "render_vcf",
    "write_vcf",
]

_FIXED_COLUMNS = ("#CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO")
_MIN_COLUMNS = 8


class VcfFormatError(ValueError):
    """Malformed VCF input (missing/duplicate header, bad columns or fields)."""


class ReferenceMismatchError(ValueError):
    """A record's CHROM is absent/duplicated in the reference or REF disagrees."""


@dataclass(frozen=True)
class VcfHeader:
    """The VCF header.

    ``meta_lines`` holds the ``##`` meta-information lines verbatim,
    without their line terminators and in input order.  ``samples``
    holds the sample names taken from the single ``#CHROM`` header line
    (an empty tuple for sample-less VCF).
    """

    meta_lines: tuple[str, ...] = ()
    samples: tuple[str, ...] = ()

    @property
    def column_names(self) -> tuple[str, ...]:
        """All column names as declared by the ``#CHROM`` line."""
        if self.samples:
            return _FIXED_COLUMNS + ("FORMAT",) + self.samples
        return _FIXED_COLUMNS


@dataclass(frozen=True)
class VcfRecord:
    """One VCF data row.

    The fixed columns are ``chrom``, ``pos`` (1-based), ``id``, ``ref``,
    ``alt`` (a tuple of ALT allele strings), ``qual``, ``filter`` and
    ``info``.  For a VCF with samples, ``format_text`` holds the FORMAT
    string and ``sample_text`` one verbatim column per sample; both are
    empty for sample-less VCF.  ``line_number`` is the 1-based source
    line of a parsed record (``0`` for records built directly).
    """

    chrom: str
    pos: int
    id: str
    ref: str
    alt: tuple[str, ...]
    qual: str
    filter: str
    info: str
    format_text: str | None = None
    sample_text: tuple[str, ...] = ()
    line_number: int = 0

    @property
    def alt_text(self) -> str:
        """The ALT column as it appears on disk."""
        return ",".join(self.alt)


@dataclass(frozen=True)
class VcfFile:
    """A parsed VCF document: a header and its records in input order.

    ``source`` is the path or stream label the document was read from
    and is used to qualify error messages during normalization.
    """

    header: VcfHeader
    records: tuple[VcfRecord, ...] = ()
    source: str = ""


def _line_error(source: str, line_number: int, message: str) -> VcfFormatError:
    return VcfFormatError(f"{source}:{line_number}: {message}")


def _is_plain_allele(allele: str) -> bool:
    """Whether *allele* is an ordinary sequence allele of real bases.

    The gVCF spanning value ``*``, the missing value ``.``, symbolic
    alleles (``<DEL>``) and break-end alleles (``]chr:123]N``, ``N.``)
    are not plain.
    """
    if not allele or allele == "*" or allele == ".":
        return False
    if "<" in allele or ">" in allele:
        return False
    if "[" in allele or "]" in allele or "." in allele or "*" in allele:
        return False
    return True


def _validate_allele(allele: str) -> str:
    """Upper-case and validate one ordinary sequence allele."""
    upper = allele.upper()
    for offset, symbol in enumerate(upper):
        if symbol not in _VALID_BASES:
            raise ValueError(
                f"invalid allele symbol {symbol!r} at offset {offset} of {allele!r}"
            )
    return upper


def _parse_pos(pos_text: str, source: str, number: int) -> int:
    if not pos_text or any(char < "0" or char > "9" for char in pos_text):
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    pos = int(pos_text)
    if pos <= 0:
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    return pos


def _parse_record_line(
    line: str, number: int, source: str, samples: Sequence[str]
) -> VcfRecord:
    fields = line.split("\t")
    if len(fields) < _MIN_COLUMNS:
        raise _line_error(
            source,
            number,
            f"expected at least 8 tab-separated columns, got {len(fields)}",
        )
    if samples:
        expected = _MIN_COLUMNS + 1 + len(samples)
        if len(fields) != expected:
            raise _line_error(
                source,
                number,
                f"expected {expected} columns to match the #CHROM header, got {len(fields)}",
            )
        format_text = fields[8]
        if not format_text:
            raise _line_error(source, number, "empty FORMAT column")
        sample_text = tuple(fields[9:])
    else:
        if len(fields) != _MIN_COLUMNS:
            raise _line_error(
                source,
                number,
                f"expected 8 columns to match the sample-less #CHROM header, "
                f"got {len(fields)}",
            )
        format_text = None
        sample_text = ()

    chrom, pos_text, ident, ref_text, alt_text, qual, flt, info = fields[:8]

    if not chrom:
        raise _line_error(source, number, "empty CHROM column")
    pos = _parse_pos(pos_text, source, number)

    if not ref_text:
        raise _line_error(source, number, "empty REF allele")
    try:
        ref = _validate_allele(ref_text)
    except ValueError as exc:
        raise _line_error(source, number, str(exc)) from None

    if not alt_text:
        raise _line_error(source, number, "empty ALT column")
    alts: list[str] = []
    for allele in alt_text.split(","):
        if allele == "":
            raise _line_error(source, number, "empty ALT allele")
        if not _is_plain_allele(allele):
            alts.append(allele)
            continue
        try:
            alts.append(_validate_allele(allele))
        except ValueError as exc:
            raise _line_error(source, number, str(exc)) from None

    return VcfRecord(
        chrom=chrom,
        pos=pos,
        id=ident,
        ref=ref,
        alt=tuple(alts),
        qual=qual,
        filter=flt,
        info=info,
        format_text=format_text,
        sample_text=sample_text,
        line_number=number,
    )


def _parse_header_line(
    line: str, number: int, source: str
) -> tuple[str, ...]:
    """Validate the ``#CHROM`` line and return its sample names."""
    columns = line.split("\t")
    if tuple(columns[:8]) != _FIXED_COLUMNS:
        raise _line_error(
            source,
            number,
            "the first eight #CHROM header columns must be exactly "
            "#CHROM\\tPOS\\tID\\tREF\\tALT\\tQUAL\\tFILTER\\tINFO",
        )
    tail = columns[8:]
    if not tail:
        return ()
    if tail[0] != "FORMAT":
        raise _line_error(
            source, number, "the ninth column, when present, must be FORMAT"
        )
    samples = tuple(tail[1:])
    if not samples:
        raise _line_error(source, number, "FORMAT column requires at least one sample")
    if any(not sample for sample in samples):
        raise _line_error(source, number, "empty sample name in #CHROM header")
    return samples


def read_vcf(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> VcfFile:
    """Read and validate a whole VCF document from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  ``##`` meta-information lines are
    kept verbatim and in order; exactly one legal ``#CHROM`` line is
    required and every data row must match its columns.  Records are
    returned in input order.

    Raises :class:`VcfFormatError` for malformed input and :class:`OSError`
    when opening a path fails.
    """
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        meta_lines: list[str] = []
        samples: tuple[str, ...] | None = None
        records: list[VcfRecord] = []

        for number, raw_line in enumerate(stream, start=1):
            line = raw_line.rstrip("\r\n")
            if line.startswith("##"):
                if samples is not None:
                    raise _line_error(
                        source_name,
                        number,
                        "meta-information line after the #CHROM header",
                    )
                meta_lines.append(line)
            elif line.startswith("#"):
                if samples is not None:
                    raise _line_error(
                        source_name, number, "duplicate #CHROM column header"
                    )
                samples = _parse_header_line(line, number, source_name)
            else:
                if samples is None:
                    raise _line_error(
                        source_name, number, "data row before the #CHROM column header"
                    )
                records.append(
                    _parse_record_line(line, number, source_name, samples)
                )

        if samples is None:
            raise VcfFormatError(
                f"{source_name}:1: missing #CHROM column header"
            )
        return VcfFile(
            VcfHeader(tuple(meta_lines), samples), tuple(records), source_name
        )
    finally:
        if close:
            stream.close()


def _build_reference(
    reference: Iterable[SequenceRecord],
) -> tuple[dict[str, str], set[str]]:
    """Map CHROM to sequence, tracking identifiers appearing more than once."""
    sequences: dict[str, str] = {}
    duplicates: set[str] = set()
    for record in reference:
        if record.identifier in sequences:
            duplicates.add(record.identifier)
        else:
            sequences[record.identifier] = record.sequence
    return sequences, duplicates


def _record_error(source: str, record: VcfRecord, message: str) -> VcfFormatError:
    if source and record.line_number:
        return VcfFormatError(f"{source}:{record.line_number}: {message}")
    if record.line_number:
        return VcfFormatError(f"line {record.line_number}: {message}")
    return VcfFormatError(message)


def _resolve_chromosome(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
) -> str:
    if record.chrom in duplicates:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than once "
            "in the reference"
        )
    try:
        return sequences[record.chrom]
    except KeyError:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: no matching record in the reference"
        ) from None


def _minimize(
    pos: int, ref: str, alts: Sequence[str]
) -> tuple[int, str, tuple[str, ...]]:
    """Remove the common suffix and prefix shared by all alleles.

    At least one base is always retained per allele and *pos* (1-based)
    is advanced by the number of stripped leading bases.
    """
    # Common suffix: compare each ALT against REF up to the shorter
    # length, always leaving at least one base per allele.
    suffix = 0
    while True:
        index = len(ref) - 1 - suffix
        if index <= 0:
            break
        ref_base = ref[index]
        ok = True
        for alt in alts:
            alt_index = len(alt) - 1 - suffix
            if alt_index <= 0 or alt[alt_index] != ref_base:
                ok = False
                break
        if not ok:
            break
        suffix += 1
    if suffix:
        ref = ref[: len(ref) - suffix]
        alts = tuple(alt[: len(alt) - suffix] for alt in alts)

    # Common prefix: at least one base must remain in every allele.
    prefix = 0
    shortest = min(len(ref), min(len(alt) for alt in alts))
    while prefix < shortest - 1 and all(
        alt[prefix] == ref[prefix] for alt in alts
    ):
        prefix += 1
    if prefix:
        ref = ref[prefix:]
        alts = tuple(alt[prefix:] for alt in alts)
        pos += prefix

    return pos, ref, tuple(alts)


def _lengths_differ(ref: str, alts: Sequence[str]) -> bool:
    return any(len(alt) != len(ref) for alt in alts)


def _normalize_against(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
    source: str,
) -> VcfRecord:
    chromosome = _resolve_chromosome(record, sequences, duplicates)

    end = record.pos - 1 + len(record.ref)
    if record.pos < 1 or end > len(chromosome):
        raise _record_error(
            source,
            record,
            f"CHROM {record.chrom} POS {record.pos}: REF of length {len(record.ref)} "
            f"is out of bounds for a reference of length {len(chromosome)}",
        )

    expected = chromosome[record.pos - 1 : end].upper()
    if expected != record.ref:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
            f"reference: expected {expected!r}, found {record.ref!r}"
        )

    if not all(_is_plain_allele(allele) for allele in record.alt):
        # Symbolic, break-end, spanning or missing ALT: verify only.
        return record

    pos, ref, alts = _minimize(record.pos, record.ref, record.alt)

    # Left-align: prepend the preceding reference base to every allele
    # and re-minimize.  A move only happens when re-minimization removes
    # a (different) right-hand base, i.e. the extended window represents
    # the same haplotypes; once a step leaves the alleles unchanged the
    # minimum POS has been reached.
    while pos > 1 and _lengths_differ(ref, alts):
        preceding = chromosome[pos - 2].upper()
        next_pos, next_ref, next_alts = _minimize(
            pos - 1,
            preceding + ref,
            tuple(preceding + alt for alt in alts),
        )
        if (next_pos, next_ref, next_alts) == (pos, ref, alts):
            break
        pos, ref, alts = next_pos, next_ref, next_alts

    return replace(record, pos=pos, ref=ref, alt=alts)


def normalize_record(
    record: VcfRecord,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfRecord:
    """Normalize one record against *reference*.

    *reference* is either a mapping of CHROM to upper-case reference
    sequence or an iterable of :class:`~genome_variant.sequence_io.SequenceRecord`
    (duplicate identifiers raise :class:`ReferenceMismatchError`).

    The REF fragment at POS is always verified.  Records whose ALT
    contains a symbolic, break-end, spanning (``*``) or missing (``.``)
    allele are returned unchanged.  Otherwise all sequence alleles are
    trimmed of their shared suffix and prefix (one base is always kept)
    and, when allele lengths differ, left-shifted across repeated
    reference bases to the smallest POS representing the same
    haplotypes, re-minimizing after every shift.  ID, QUAL, FILTER,
    INFO, FORMAT, sample text and ALT order are preserved.

    Raises :class:`ReferenceMismatchError` for an absent/duplicate CHROM
    or a REF that disagrees with the reference, and
    :class:`VcfFormatError` for a record that runs past the reference.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)
    return _normalize_against(record, sequences, duplicates, "")


def normalize_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfFile:
    """Normalize every record of *document* against *reference*.

    Record order is preserved; see :func:`normalize_record` for the
    per-record rules.  Every record is validated before the normalized
    document is returned, so an error never comes with partial output.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)

    normalized = tuple(
        _normalize_against(record, sequences, duplicates, document.source)
        for record in document.records
    )
    return VcfFile(document.header, normalized, document.source)


def _record_line(record: VcfRecord) -> str:
    fields = [
        record.chrom,
        str(record.pos),
        record.id,
        record.ref,
        record.alt_text,
        record.qual,
        record.filter,
        record.info,
    ]
    if record.format_text is not None:
        fields.append(record.format_text)
        fields.extend(record.sample_text)
    return "\t".join(fields)


def render_vcf(document: VcfFile) -> str:
    """Serialize *document* to VCF text.

    Output uses tabs and ``"\\n"`` line endings and always ends with
    exactly one trailing newline; a record-less VCF still writes the
    complete header (``##`` lines followed by the ``#CHROM`` line).
    """
    lines = list(document.header.meta_lines)
    lines.append("\t".join(document.header.column_names))
    lines.extend(_record_line(record) for record in document.records)
    return "\n".join(lines) + "\n"


def write_vcf(
    document: VcfFile,
    output: "str | os.PathLike[str] | io.TextIOBase",
) -> None:
    """Write *document* to *output* as VCF text.

    Tabs and ``"\\n"`` are used throughout with exactly one trailing
    newline; an empty-record VCF still writes the complete header.
    """
    text = render_vcf(document)
    if isinstance(output, io.IOBase):
        output.write(text)
    elif isinstance(output, (str, os.PathLike)):
        with open(os.fspath(output), "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
    else:
        raise TypeError("output must be a text path or a text stream")

